#!/usr/bin/env python3
# gen_bmi270_cfg.py - regenerate hal/device/cp_bmi270_cfg.py from Bosch's
# BMI270_SensorAPI (github.com/boschsensortec/BMI270_SensorAPI, bmi270.c).
# Only needed if Bosch ever changes the blob; the generated file is committed.
#
#   tools/gen_bmi270_cfg.py <path to BMI270_SensorAPI/bmi270.c>
import re, sys, os, hashlib

PORT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = open(sys.argv[1]).read()
lic = src[:src.index('* @file')].strip()
body = src[src.index('bmi270_config_file[] = {') + len('bmi270_config_file[] = {'):]
body = body[:body.index('};')]
data = bytes(int(x, 16) for x in re.findall(r'0x[0-9a-fA-F]{2}', body))
if len(data) != 8192:
    sys.exit('unexpected config size %d' % len(data))
h = hashlib.sha256(data).hexdigest()
lines = ['# cp_bmi270_cfg.py - Cardputer port: configuration blob the Bosch BMI270',
         '# motion sensor needs uploaded at power-up (bmi270_config_file[] from Bosch',
         '# Sensortec BMI270_SensorAPI v2.86.1, bmi270.c). Generated by',
         '# tools/gen_bmi270_cfg.py; sha256 %s.' % h,
         '#', '# Original notice:', '#']
for ln in lic.split('\n'):
    ln = ln.strip().lstrip('/').lstrip('*').rstrip()
    lines.append(('# ' + ln.strip()).rstrip())
lines += ['', 'CONFIG = (']
for i in range(0, len(data), 32):
    lines.append('    b"' + ''.join('\\x%02x' % b for b in data[i:i + 32]) + '"')
lines += [')', 'SHA256 = %r' % h]
out = os.path.join(PORT, 'hal', 'device', 'cp_bmi270_cfg.py')
open(out, 'w').write('\n'.join(lines) + '\n')
print('wrote', out, h)
